          });
        });
      }
    }
  } catch (err) {
    throw new Error("Invalid JSON in input item: " + err.message);
  }
}

const riskData = { High: [], Medium: [], Low: [], Informational: [] };
combined.forEach(entry => {
  const risk = entry.risk || 'Informational';
  riskData[risk]?.push(entry);
});

const categoryStyles = {
