    <div class="container">
        <div class="header">
            <div class="header-content">
                <h1>CAD Project Batch Conversion Report</h1>
                <p class="subtitle">Automated conversion pipeline execution summary</p>
                <p class="timestamp">${now.toLocaleString('en-US', { 
                    weekday: 'long', 
                    year: 'numeric', 
                    month: 'long', 
                    day: 'numeric', 
                    hour: '2-digit', 
                    minute: '2-digit' 
                })}</p>
            </div>
        </div>

        <div class="content">
            <div class="metrics">
                <div class="metric">
                    <div class="metric-value">${totalFiles}</div>
                    <div class="metric-label">Total Files</div>
                </div>
                <div class="metric highlight">
                    <div class="metric-value">${successRate}%</div>
                    <div class="metric-label">Success Rate</div>
                </div>
                <div class="metric">
                    <div class="metric-value">${totalPipelineMinutes}</div>
                    <div class="metric-label">Total Time (Minutes)</div>
                </div>
                <div class="metric">
                    <div class="metric-value">${Math.round(totalInputSize / 1048576)} MB</div>
                    <div class="metric-label">Total Input Size</div>
                </div>
                <div class="metric">
                    <div class="metric-value">${Math.round(totalOutputSize / 1048576)} MB</div>
                    <div class="metric-label">Total Output Size</div>
                </div>
            </div>

            <div class="report-location">
                <strong>Report Location:</strong> ${fullPath}
            </div>

            ${noColladaEnabled ? `
            <div class="no-collada-notice">
                <strong>Note:</strong> DAE (Collada) file generation was skipped as per configuration (no-collada option enabled).
            </div>
            ` : ''}

            ${successfulFiles.length > 0 ? `
            <div class="section">
                <div class="section-header">
                    <h2>✅ Successfully Converted Files (${successfulFiles.length})</h2>
                </div>
                <div class="section-content">
                    <table>
                        <thead>
                            <tr>
                                <th>File Name</th>
                                <th>Original Size</th>
                                <th>Excel Output</th>
                                ${noColladaEnabled ? '<th>DAE Output</th>' : '<th>DAE Output</th>'}
                                <th>Total Output</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${successfulFiles.map(file => `
                                <tr>
                                    <td><strong>${file.name}</strong></td>
                                    <td class="size-cell">${file.originalSize} KB</td>
                                    <td class="size-cell">
                                        <a href="file:///${file.xlsxPath.replace(/\\/g, '/')}" class="file-link" target="_blank">${file.xlsxSize} KB</a>
                                    </td>
                                    <td class="size-cell">
                                        ${noColladaEnabled ? 
                                            '<span class="status-skipped">SKIPPED</span>' : 
                                            `<div class="tooltip">
                                                <a href="file:///${file.daePath.replace(/\\/g, '/')}" class="file-link" target="_blank">${file.daeSize} KB</a>
                                                <span class="tooltiptext">💡 Tip: Use the free CAD Assistant software for the best viewing experience of DAE files</span>
                                            </div>`
                                        }
                                    </td>
                                    <td class="size-cell"><strong>${file.totalSize} KB</strong></td>
                                </tr>
                            `).join('')}
                        </tbody>
                    </table>
                </div>
            </div>
            ` : ''}

            ${failedFiles.length > 0 ? `
            <div class="section">
                <div class="section-header">
                    <h2>❌ Failed Conversions (${failedFiles.length})</h2>
                </div>
                <div class="section-content">
                    <table>
                        <thead>
                            <tr>
                                <th>File Name</th>
                                <th>Original Size</th>
                                <th>XLSX Status</th>
                                <th>DAE Status</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${failedFiles.map(file => `
                                <tr>
                                    <td><strong>${file.name}</strong></td>
                                    <td class="size-cell">${file.originalSize} KB</td>
                                    <td><span class="status-${file.xlsxStatus === '✓' ? 'success' : 'failed'}">${file.xlsxStatus === '✓' ? 'SUCCESS' : 'FAILED'}</span></td>
                                    <td>${noColladaEnabled && file.xlsxStatus === '✓' ? 
                                        '<span class="status-skipped">SKIPPED</span>' : 
                                        `<span class="status-${file.daeStatus === '✓' ? 'success' : 'failed'}">${file.daeStatus === '✓' ? 'SUCCESS' : 'FAILED'}</span>`
                                    }</td>
                                </tr>
                            `).join('')}
                        </tbody>
                    </table>
                </div>
            </div>
            ` : ''}

            <div class="config-section">
                <h2 style="color: #1e293b; font-size: 1.4rem; font-weight: 600; margin-bottom: 20px;">
                    ⚙️ Configuration Details
                </h2>
                <div class="config-grid">
                    <div class="config-item">
                        <span class="config-label">Source Folder:</span>
                        <span class="config-value">${config.source_folder || 'Not specified'}</span>
                    </div>
                    <div class="config-item">
                        <span class="config-label">Output Folder:</span>
                        <span class="config-value">${config.output_folder || 'Not specified'}</span>
                    </div>
                    <div class="config-item">
                        <span class="config-label">File Extension:</span>
                        <span class="config-value">${config.file_extension || 'Not specified'}</span>
                    </div>
                    <div class="config-item">
                        <span class="config-label">Include Subfolders:</span>
                        <span class="config-value">${config.include_subfolders ? 'Yes' : 'No'}</span>
                    </div>
                    <div class="config-item">
                        <span class="config-label">Converter Options:</span>
                        <span class="config-value">${config.options || 'None'}</span>
                    </div>
                    <div class="config-item">
                        <span class="config-label">Generated:</span>
                        <span class="config-value">${now.toLocaleString()}</span>
                    </div>
                    <div class="config-item">
                        <span class="config-label">Workflow ID:</span>
                        <span class="config-value">FYFQhblt4gILLSpe</span>
                    </div>
                </div>
            </div>
        </div>

        <div class="footer">
            <div class="company">DataDrivenConstruction.io</div>
            <div>Professional CAD Conversion Pipeline</div>
            <div class="version">Version 2.0 | Automated Batch Processing System</div>
        </div>
    </div>
</body>
</html>`;

